function authenticV10ObserverSource(contents) {
  const original = contents.replace('assert.equal(result.rows.length, protocolPairs.length);', 'assert.equal(result.rows.length, 20);');
  assert.equal(createHash('sha256').update(original).digest('hex'),
    nativePass.nativePlacementPhasesV10.phases[2].sourceDigest);
  return original;
}

function authenticV13CatalogSource(contents) {
  const reason = 'PR-only owned producer/admission boundary. Starting a real new fixture execution needs the bound working directory, not replay of prior outcomes; immutable-page corruption and loss still fail closed at admission and fresh reload.';
  contents = contents.replace('PR-only owned producer/admission boundary. Real fixture execution and admission do not depend on an unused caller-authored report; starting the producer needs the bound working directory, not replay of prior outcomes. Immutable-page corruption and loss still fail closed at admission and fresh reload.', reason)
    .replace('async function submit(f, cycle, tests, statuses = {}) {\n' +
      '  await recordFixtureTests(f.store, cycle, tests, statuses);\n}',
    'async function submit(f, cycle, tests, statuses = {}) {\n' +
      '  const retained = await report(f, cycle, tests, statuses);\n' +
      '  await recordFixtureTests(f.store, cycle, tests, statuses);\n' +
      '  return retained;\n}');
  const next = contents.indexOf("  const nextUnit = cycleTests(selected).find(test => test.level === 'unit' && test.id !== unit.id);");
  const nextEnd = contents.indexOf('\n});', next);
  assert.ok(next > 0 && nextEnd > next);
  contents = contents.slice(0, next) + contents.slice(nextEnd + 1);
  assert.equal(createHash('sha256').update(contents).digest('hex'),
    nativePass.nativePlacementServiceV14.catalog.sourceDigest, 'Preserve the exact original C81 fixture source first');
  const control = '\n  }, {\n    "root": "published references are fresh-checked after cache use and missing/corrupt pages cannot become success",\n    "minimumSlots": 6';
  const classification = '\n  }, {\n    "names": ["published references are fresh-checked after cache use and missing/corrupt pages cannot become success"],\n' +
    '    "platforms": ["linux-x64", "windows-x64", "macos-arm64", "macos-x64"],\n' +
    '    "owner": "catalog-service-contract",\n' +
    '    "reason": "PR-only owned producer/admission boundary. Starting a real new fixture execution needs the bound working directory, not replay of prior outcomes; immutable-page corruption and loss still fail closed at admission and fresh reload.",\n' +
    '    "prerequisites": ["Node, Git and six aggregate worker slots; owned repository-local repository and Copilot home"]';
  const restored = contents.replace(control, '').replace(classification, '');
  const root = restored.indexOf("test('published references are fresh-checked after cache use and missing/corrupt pages cannot become success',");
  const end = restored.indexOf('\n});', root);
  const start = restored.indexOf("  const unit = cycleTests(cycle).find(test => test.level === 'unit');", root);
  assert.ok(root > 0 && start > root && end > start);
  const original = restored.slice(0, start) + restored.slice(end + 1);
  assert.equal(createHash('sha256').update(original).digest('hex'),
    nativePass.nativePlacementReservationV13.catalog.sourceDigest);
  return original;
}

function authenticV12CatalogSource(contents) {
  contents = authenticV13CatalogSource(contents);
  const start = contents.indexOf('  "groups": [{');
  const end = contents.indexOf('  "variants": [', start);
  assert.ok(start > 0 && end > start);
  const original = contents.slice(0, start) + contents.slice(end);
  assert.equal(createHash('sha256').update(original).digest('hex'),
    nativePass.nativePlacementPhasesV9.phases[0].sourceDigest);
  return original;
}

async function nativeIsolationFixture(t, options = {}) {
  const f = await nativeAffinityFixture(t, { bootstrapProtocol: nativeCryptoBootstrapProtocol, ...options });
  const catalog = f.files.find(source => source.file === 'test/validation-catalog.test.mjs');
  catalog.contents = authenticV12CatalogSource(
    await fs.readFile(path.join(repositoryRoot, 'test', 'validation-catalog.test.mjs'), 'utf8'));
  const file = 'test/github-host-authority.test.mjs';
  f.files.push({ file, contents: await fs.readFile(path.join(repositoryRoot, ...file.split('/')), 'utf8') });
  const surface = 'src/github/store-bridge.mjs';
  f.files.push({ file: surface, contents: await fs.readFile(path.join(repositoryRoot, ...surface.split('/')), 'utf8') });
  const observer = f.files.find(source => source.file === 'test/public-readiness-observer.test.mjs');
  const historical = await qualifiedIntelSourceFiles();
  const retained = f.files.find(source => source.file === f.retainedFile);
  retained.contents = historical.files.find(source => source.file === f.retainedFile).contents;
  observer.contents = historical.files.find(source => source.file === observer.file).contents;
  if (options.shardProtocol === 'native-framework-shards-v10-phased-intel-component-rebalance')
    observer.contents = authenticV10ObserverSource(observer.contents);
  for (const file of ['scripts/github-readiness-host.mjs', 'scripts/pr-observer.mjs', 'scripts/read-validation-artifact.py']) {
    const contents = await fs.readFile(path.join(repositoryRoot, ...file.split('/')), 'utf8');
    const selected = f.files.find(source => source.file === file);
    if (selected) selected.contents = contents;
    else f.files.push({ file, contents });
  }
  return { ...f, inventory: f.compile(f.files) };
}

async function intelGitSourceInventory() {
  const inventory = await compileValidationInventory(repositoryRoot);
  assert.equal(inventory.complete, true, JSON.stringify(inventory.unresolved));
  const files = await Promise.all(inventory.sourceFiles.map(async ({ file }) => ({
    file,
    contents: (await fs.readFile(path.join(repositoryRoot, ...file.split('/')), 'utf8'))
      .replace(/\r\n/gu, '\n'),
  })));
  return compileValidationSourceInventory({ files,
    surfacePaths: [...new Set(inventory.surfaces.map(surface => surface.path))] });
}

